# In-memory pixmap and icon caches
_PIXMAP_CACHE: Dict[Tuple[str, int, int, str], QPixmap] = {}
_ICON_CACHE: Dict[Tuple[str, int, str], QIcon] = {}


def get_icon_pixmap(
    icon_name: str,
    width: int = 18,
    height: Optional[int] = None,
    color: Optional[str] = None,
) -> QPixmap:
    """
    Render clean vector SVG icon as a high-DPI antialiased QPixmap.
    """
    if height is None:
        height = width

    key_name = (icon_name or "").lower().strip()
    color_val = color or "#007AFF"
    cache_key = (key_name, width, height, color_val)

    if cache_key in _PIXMAP_CACHE:
        return _PIXMAP_CACHE[cache_key]

    svg_data = ICON_SVGS.get(key_name)
    if not svg_data:
        # Fallback to info or check
        svg_data = ICON_SVGS.get("info", ICON_SVGS["flash"])

    # Tint stroke or fill: ensure vivid accent or specified color is always applied
    effective_color = color or "#0A84FF"
    svg_data = svg_data.replace('stroke="currentColor"', f'stroke="{effective_color}"')
    svg_data = svg_data.replace('fill="currentColor"', f'fill="{effective_color}"')

    renderer = QSvgRenderer(QByteArray(svg_data.strip().encode("utf-8")))
    pixmap = QPixmap(width, height)
    pixmap.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    renderer.render(painter)
    painter.end()

    _PIXMAP_CACHE[cache_key] = pixmap
    return pixmap


def get_icon(
    icon_name: str,
    size: int = 18,
    color: Optional[str] = None,
) -> QIcon:
    """
    Return a QIcon wrapping the rendered vector SVG image.
    """
    pix = get_icon_pixmap(icon_name, width=size, height=size, color=color)
    return QIcon(pix)


def create_icon_label(
    icon_name: str,
    size: int = 18,
    color: Optional[str] = None,
    parent: Optional[QWidget] = None,
) -> QLabel:
    """
    Create a lightweight QLabel displaying the rendered vector image.
    """
    lbl = QLabel(parent)
    lbl.setFixedSize(size, size)
    pix = get_icon_pixmap(icon_name, width=size, height=size, color=color)
    lbl.setPixmap(pix)
    lbl.setScaledContents(True)
    lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
    return lbl
